const LEVELS=["A1","A2","B1","B2","C1","C2"];
const $=s=>document.querySelector(s);
let db=JSON.parse(localStorage.getItem("polyglot-pro")||'{"done":[],"known":[],"points":0,"minutes":0,"level":{"es":"A1","ru":"A1","fr":"A1","de":"A1"},"active":"es","review":[],"quizCorrect":0,"unitQuiz":{},"placement":{},"badges":[],"listenCorrect":0,"streakDays":1,"storiesRead":[],"speakCorrect":0,"daily":{},"verbCorrect":0,"writeCount":0,"writeDay":null}');db.unitQuiz=db.unitQuiz||{};db.daily=db.daily||{};db.storiesRead=db.storiesRead||[];
let page="dashboard",lang=db.active,unitIndex=0,quiz=[],qi=0,flash=0,flashFilter="all";
const allWords=LANGS.flatMap(l=>l.units.flatMap((u,i)=>[{id:l.id,flag:l.flag,word:u[1],meaning:u[2]},{id:l.id,flag:l.flag,word:u[3],meaning:u[4]}]).concat(l.words.map(w=>({id:l.id,flag:l.flag,word:w[0],meaning:w[1]}))));
let lastPts=db.points;
function addDaily(){let d=db.points-lastPts;lastPts=db.points;if(d>0){db.daily=db.daily||{};let k=new Date().toDateString();db.daily[k]=(db.daily[k]||0)+d}}
function save(){addDaily();let fresh=checkBadges();localStorage.setItem("polyglot-pro",JSON.stringify(db));fresh.forEach((b,i)=>setTimeout(()=>toast("🏅 إنجاز جديد: "+b.name+"!"),400+i*2400))}
function toast(s){let e=$("#toast");e.textContent=s;e.classList.add("show");setTimeout(()=>e.classList.remove("show"),2300)}
function doneCount(id){return db.done.filter(k=>k.startsWith(id+"-")).length}
function pct(id){return Math.round(doneCount(id)/(LANGS.find(l=>l.id===id).units.length*6)*100)}
function go(p){page=p;document.querySelectorAll(".nav").forEach(n=>n.classList.toggle("active",n.dataset.page===p));$("#sidebar").classList.remove("open");({dashboard:home,languages:languagesPage,tutor:tutorPage,practice:practicePage,vocabulary:vocabPage,review:reviewPage,progress:progressPage,achievements:achievementsPage,stories:storiesPage}[p]())}
function title(t){$("#pageTitle").textContent=t}
function home(){title("لوحة التعلم");$("#content").innerHTML=`
<div class="hero"><div class="hero-copy"><span class="eyebrow">تعلم اليوم، وتحدث بثقة غداً</span><h1>أربع لغات. عالم من الفرص. 🌍</h1><p>خطتك الشخصية لتعلم الإسبانية والروسية والفرنسية والألمانية من الصفر.</p><button class="btn light" onclick="go('languages')">ابدأ رحلتك التعليمية ←</button></div><div class="hero-art">🌐</div></div>
<div class="stats"><div class="stat"><div class="stat-icon">📚</div><div><small>الدروس المكتملة</small><b>${db.done.length}</b></div></div><div class="stat"><div class="stat-icon">⭐</div><div><small>النقاط</small><b>${db.points}</b></div></div><div class="stat"><div class="stat-icon">🧠</div><div><small>كلمات أتقنتها</small><b>${db.known.length}</b></div></div><div class="stat"><div class="stat-icon">⏱️</div><div><small>دقائق التعلم</small><b>${db.minutes}</b></div></div></div>
<div class="panel" style="margin-top:14px"><div class="card-foot"><h3 style="margin:0">📈 نشاطك هذا الأسبوع</h3><small>النقاط المكتسبة يومياً</small></div>${weekChart()}</div>
<div class="section-head"><h3>📅 كلمة اليوم</h3><small>كلمة جديدة كل يوم لكل لغة · اضغطها لفتح البطاقات</small></div><div class="wotd-grid">${wotd().map(x=>`<div class="wotd-card" onclick="wotdOpen('${x.l.id}',${x.i})"><div class="card-foot"><span>${x.l.flag} ${x.l.name}</span><button class="icon-btn sm" onclick="event.stopPropagation();speak('${x.v.word.replace(/'/g,"\\'")}','${x.l.id}')">🔊</button></div><b dir="auto">${x.v.word}</b><small>${x.v.meaning}</small></div>`).join("")}</div>
<div class="section-head"><h3>مساراتك التعليمية</h3><small>اختر لغة لمتابعة التعلم</small></div><div class="language-grid">${LANGS.map(l=>`<article class="language-card" style="--accent:${l.color}"><div class="lang-head"><span class="flag">${l.flag}</span><span class="tag">${db.level[l.id]}</span></div><h3>${l.name}</h3><p>${l.native} · ${doneCount(l.id)} درس مكتمل</p><div class="track"><span style="width:${pct(l.id)}%"></span></div><div class="card-foot"><span>${pct(l.id)}% إنجاز</span><button onclick="openLang('${l.id}')">متابعة ←</button></div></article>`).join("")}</div>
<div class="two-col"><div class="panel"><h3>🎯 خطة اليوم المقترحة</h3><div class="task"><div class="task-icon">📖</div><div><b>درس جديد</b><small>تعلم موضوعاً جديداً في ${LANGS.find(l=>l.id===lang).name}</small></div><button class="btn" onclick="go('languages')">ابدأ</button></div><div class="task"><div class="task-icon">🧠</div><div><b>مراجعة المفردات</b><small>راجع بطاقاتك قبل أن تنساها</small></div><button class="btn" onclick="go('review')">راجع</button></div><div class="task"><div class="task-icon">✍️</div><div><b>اختبار سريع</b><small>تحقق من فهمك للمفردات</small></div><button class="btn" onclick="go('practice')">اختبر</button></div></div><div class="panel"><h3>✨ نصيحة تعلم</h3><div class="quote">خصص 20 دقيقة يومياً: 5 دقائق مفردات، 10 دقائق درس، و5 دقائق تحدث بصوت مرتفع. الانتظام هو سر اكتساب اللغة.</div></div></div>`}
function languagesPage(){title("اللغات والمناهج");$("#content").innerHTML=`<p class="page-intro">لكل لغة ستة مستويات تعليمية. اختر اللغة ثم المستوى المناسب لك.</p><div class="course-grid">${LANGS.map(l=>`<div class="language-card"><div class="course-row"><span class="flag">${l.flag}</span><div><h3>${l.name}</h3><p>${l.native} · 6 مستويات</p></div><button class="btn" onclick="openLang('${l.id}')">فتح المنهج</button></div><div class="track"><span style="width:${pct(l.id)}%;background:${l.color}"></span></div><div class="card-foot"><span>المستوى الحالي: ${db.level[l.id]}</span><span>${pct(l.id)}%</span></div></div>`).join("")}</div><div id="curriculum"></div>`}
function openLang(id){lang=id;db.active=id;save();let l=LANGS.find(x=>x.id===id);$("#curriculum").innerHTML=`<div class="section-head"><h3>${l.flag} منهج ${l.name}</h3><span><button class="btn ghost" onclick="pracMode='place';lang='${id}';go('practice')">🧭 حدد مستواك</button></span></div><div class="level-grid">${LEVELS.map((lv,i)=>`<button class="level ${db.level[id]===lv?"active":""}" onclick="setLevel('${id}','${lv}')"><b>${lv}</b><small>${l.levels[i]}</small></button>`).join("")}</div><div class="section-head"><h3>وحدات المستوى ${db.level[id]}</h3><small>عبارات + قواعد + اختبار لكل وحدة</small></div><div class="lesson-list">${l.units.map((u,i)=>`<div class="lesson"><div class="lesson-num">${i+1}</div><div><b>${u[0]}</b><small>${u[1]} — ${u[2]}</small>${db.unitQuiz[id+"-"+db.level[id]+"-"+i]!=null?`<small style="color:var(--purple)">🏅 أفضل نتيجة: ${db.unitQuiz[id+"-"+db.level[id]+"-"+i]}/5</small>`:""}</div><button class="btn ${db.done.includes(id+"-"+db.level[id]+"-"+i)?"ghost":""}" onclick="lesson('${id}',${i})">${db.done.includes(id+"-"+db.level[id]+"-"+i)?"مراجعة":"افتح الدرس"}</button></div>`).join("")}</div>`;$("#curriculum").scrollIntoView({behavior:"smooth",block:"start"})}
function setLevel(id,lv){db.level[id]=lv;save();openLang(id);toast("تم اختيار المستوى "+lv)}
function lesson(id,i){lang=id;unitIndex=i;let l=LANGS.find(x=>x.id===id),u=l.units[i],key=id+"-"+db.level[id]+"-"+i,g=GRAMMAR[id]&&GRAMMAR[id][i],best=db.unitQuiz[key];
let gr=g?`<div class="grammar"><h4>📘 قاعدة الوحدة: ${g[0]}</h4><p>${g[1]}</p><div class="tbl-wrap"><table class="md-table"><tr>${g[2].map(h=>`<th>${h}</th>`).join("")}</tr>${g[3].map(r=>`<tr>${r.map((c,k)=>`<td dir="auto">${c}${k===r.length-1&&/[A-Za-zА-Яа-яЁёÀ-ÿ]/.test(c)?` <button class="icon-btn sm" onclick="speak('${c.replace(/'/g,"\\'")}','${id}')">🔊</button>`:""}</td>`).join("")}</tr>`).join("")}</table></div></div>`:"";
$("#curriculum").innerHTML=`<div class="section-head"><h3>${l.flag} ${u[0]}</h3><small>${db.level[id]} · الوحدة ${i+1} من ${l.units.length}</small></div><div class="panel"><p class="page-intro">اقرأ العبارة، استمع إلى نطقها، ثم كررها بصوت واضح.</p><div class="quote" style="font-size:18px;text-align:center;margin-bottom:10px"><span dir="ltr">${u[1]}</span> <button class="icon-btn" onclick="speak('${u[1].replace(/'/g,"\\'")}','${id}')">🔊</button><br><small>${u[2]}</small></div><div class="quote" style="font-size:18px;text-align:center"><span dir="ltr">${u[3]}</span> <button class="icon-btn" onclick="speak('${u[3].replace(/'/g,"\\'")}','${id}')">🔊</button><br><small>${u[4]}</small></div>${gr}<p class="subtext">مهمة الدرس: كرر الجملتين ثلاث مرات وحاول استخدامهما في جملة من إنشائك.${best!=null?` · أفضل نتيجة في اختبار الوحدة: ${best}/5`:""}</p><div class="center-actions" style="justify-content:flex-start"><button class="btn" onclick="complete('${key}')">إكمال الدرس ✓</button> <button class="btn dark" onclick="startUnitQuiz('${id}',${i})">📝 اختبار الوحدة</button> <button class="btn ghost" onclick="go('tutor')">اسأل المدرس الذكي</button> <button class="btn ghost" onclick="openLang('${id}')">← الوحدات</button></div></div>`;$("#curriculum").scrollIntoView({behavior:"smooth",block:"start"})}
function sh(a){return a.slice().sort(()=>Math.random()-.5)}
function startUnitQuiz(id,i){lang=id;unitIndex=i;let l=LANGS.find(x=>x.id===id),u=l.units[i],g=GRAMMAR[id][i],others=l.units.filter((_,k)=>k!==i),fo=others.flatMap(x=>[x[1],x[3]]),ar=others.flatMap(x=>[x[2],x[4]]);
let mk=(q,a,pool,label,isAr)=>({q,a,label,ar:isAr,lid:id,opts:sh([a].concat(sh(pool.filter(x=>x!==a)).slice(0,2)))});
quiz=[mk(u[1],u[2],ar,"ما معنى العبارة التالية؟",false),mk(u[3],u[4],ar,"ما معنى العبارة التالية؟",false),mk(u[2],u[1],fo,"كيف تقول هذه العبارة؟",true),mk(u[4],u[3],fo,"كيف تقول هذه العبارة؟",true),{q:g[4][0],a:g[4][1],label:"سؤال القاعدة: "+g[0],ar:true,opts:sh(g[4].slice(1))}];
quiz.unit={id,i};qi=0;quiz.score=0;go_unitQ()}
function go_unitQ(){title("اختبار الوحدة");let host=$("#curriculum")||$("#content");if(!$("#quiz")){host.innerHTML='<div class="quiz-box" id="quiz"></div>'}showQ()}
function complete(k){if(!db.done.includes(k)){db.done.push(k);db.points+=25;db.minutes+=10}save();toast("رائع! أضفنا 25 نقطة و10 دقائق تعلم ⭐");openLang(lang)}
function speak(t,id){if(!("speechSynthesis"in window)){toast("النطق غير مدعوم في هذا المتصفح");return}speechSynthesis.cancel();let l=LANGS.find(x=>x.id===id),u=new SpeechSynthesisUtterance(t);u.lang=l.voice;u.rate=.95;let vs=speechSynthesis.getVoices(),v=vs.find(x=>x.lang===l.voice)||vs.find(x=>x.lang&&x.lang.toLowerCase().startsWith(l.voice.slice(0,2).toLowerCase()));if(v)u.voice=v;speechSynthesis.speak(u)}
if("speechSynthesis"in window)speechSynthesis.getVoices();
let pracMode="quiz";
function practicePage(){title("الاختبارات والتدريب");$("#content").innerHTML=`<p class="page-intro">اختبر مفرداتك، درّب أذنك على الاستماع، أو حدد مستواك بدقة.</p><div class="tabs"><button class="tab ${pracMode==="quiz"?"active":""}" onclick="pracMode='quiz';practicePage()">✎ اختبار سريع</button><button class="tab ${pracMode==="listen"?"active":""}" onclick="pracMode='listen';practicePage()">🎧 تمارين الاستماع</button><button class="tab ${pracMode==="place"?"active":""}" onclick="pracMode='place';practicePage()">🧭 تحديد المستوى</button><button class="tab ${pracMode==="speak"?"active":""}" onclick="pracMode='speak';practicePage()">🎤 تمرين الكلام</button><button class="tab ${pracMode==="daily"?"active":""}" onclick="pracMode='daily';practicePage()">🎯 تحدي اليوم</button><button class="tab ${pracMode==="verb"?"active":""}" onclick="pracMode='verb';practicePage()">🔠 تصريف الأفعال</button><button class="tab ${pracMode==="write"?"active":""}" onclick="pracMode='write';practicePage()">✍️ تصحيح الكتابة</button></div><div class="tabs">${LANGS.map(l=>`<button class="tab ${lang===l.id?"active":""}" onclick="lang='${l.id}';practicePage()">${l.flag} ${l.name}</button>`).join("")}</div><div id="prac"></div>`;renderPrac()}
function renderPrac(){if(pracMode==="verb")verbHome();else if(pracMode==="write")writeHome();else if(pracMode==="daily")dailyHome();else if(pracMode==="listen")listenHome();else if(pracMode==="place")placeHome();else if(pracMode==="speak")speakHome();else $("#prac").innerHTML=`<div class="quiz-box" id="quiz"><div class="empty">اختبار من 10 أسئلة مع نتيجة فورية وتسجيل النقاط.<br><br><button class="btn" onclick="startQuiz()">ابدأ الاختبار</button></div></div>`}
function startQuiz(){let l=LANGS.find(x=>x.id===lang),all=l.units.map(u=>[u[1],u[2]]).concat(l.units.map(u=>[u[3],u[4]])).concat(l.words);let pick=all.slice().sort(()=>Math.random()-.5).slice(0,10);quiz=pick.map(p=>{let wrong=all.filter(x=>x[1]!==p[1]).sort(()=>Math.random()-.5).slice(0,2).map(x=>x[1]);return{q:p[0],a:p[1],lid:lang,opts:[p[1]].concat(wrong).sort(()=>Math.random()-.5)}});qi=0;quiz.score=0;showQ()}
function showQ(){if(qi>=quiz.length&&quiz.unit){finishUnitQuiz();return}if(qi>=quiz.length&&quiz.daily){finishDaily();return}if(qi>=quiz.length&&quiz.placement){finishPlacement();return}if(qi>=quiz.length){$("#quiz").innerHTML=`<div class="empty"><div style="font-size:40px">🏆</div><h2>انتهى الاختبار!</h2><p>نتيجتك: ${quiz.score} من ${quiz.length}</p><button class="btn" onclick="startQuiz()">إعادة الاختبار</button></div>`;return}let q=quiz[qi];$("#quiz").innerHTML=`<div class="card-foot"><span>${quiz.unit?"اختبار الوحدة · ":quiz.placement?"تحديد المستوى · ":quiz.daily?"تحدي اليوم · ":""}السؤال ${qi+1} من ${quiz.length}</span><span>⭐ ${db.points} نقطة</span></div><div class="track"><span style="width:${qi/quiz.length*100}%"></span></div><div class="question">${q.label||"ما معنى العبارة التالية؟"}</div><div class="foreign" dir="${q.ar?"rtl":"ltr"}" style="${q.ar?"text-align:right;font-family:Cairo;font-size:16px":""}">${q.q}${!q.ar&&q.lid?` <button class="icon-btn sm" onclick="speak('${q.q.replace(/'/g,"\\'")}','${q.lid}')">🔊</button>`:""}</div><div class="answers">${q.opts.map(a=>`<button class="answer" onclick="answer(this,'${a.replace(/'/g,"\\'")}')">${a}</button>`).join("")}</div><div class="feedback" id="fb"></div><button class="btn" id="next" style="display:none" onclick="qi++;showQ()">التالي ←</button>`}
function answer(el,a){let q=quiz[qi];document.querySelectorAll(".answer").forEach(x=>x.disabled=true);if(a===q.a){el.classList.add("correct");$("#fb").textContent="إجابة صحيحة! +10 نقاط";quiz.score++;db.points+=10;db.quizCorrect++}else{el.classList.add("wrong");$("#fb").textContent="الإجابة الصحيحة: "+q.a;document.querySelectorAll(".answer").forEach(x=>{if(x.textContent===q.a)x.classList.add("correct")})}save();$("#next").style.display="inline-block"}
function vocabPage(){title("مفرداتي");let list=allWords.filter(x=>flashFilter==="all"||x.id===flashFilter);flash=flash%list.length;let v=list[flash];$("#content").innerHTML=`<p class="page-intro">بطاقات تعليمية لتثبيت المفردات. اضغط على البطاقة لإظهار الترجمة.</p><div class="tabs"><button class="tab ${flashFilter==="all"?"active":""}" onclick="flashFilter='all';flash=0;vocabPage()">كل اللغات</button>${LANGS.map(l=>`<button class="tab ${flashFilter===l.id?"active":""}" onclick="flashFilter='${l.id}';flash=0;vocabPage()">${l.flag} ${l.name}</button>`).join("")}</div><div class="flashcard" id="flashcard" onclick="flipCard()"><small>${v.flag} بطاقة ${flash+1} من ${list.length}</small><strong dir="auto">${v.word}</strong><small>اضغط لإظهار المعنى</small></div><div class="center-actions"><button class="btn ghost" onclick="flash=(flash-1+${list.length})%${list.length};vocabPage()">→ السابقة</button><button class="btn" onclick="flash=(flash+1)%${list.length};vocabPage()">التالية ←</button><button class="btn ghost" onclick="speak('${v.word.replace(/'/g,"\\'")}','${v.id}')">🔊 استمع</button><button class="btn dark" onclick="known('${v.word.replace(/'/g,"\\'")}')">أتقنتها ✓</button></div><p class="subtext" style="text-align:center;margin-top:14px">عدد الكلمات التي أتقنتها: ${db.known.length}</p>`}
function flipCard(){let v=allWords.filter(x=>flashFilter==="all"||x.id===flashFilter)[flash%allWords.filter(x=>flashFilter==="all"||x.id===flashFilter).length],e=$("#flashcard");e.classList.toggle("revealed");e.querySelector("strong").textContent=e.classList.contains("revealed")?v.meaning:v.word;e.querySelector("small:last-child").textContent=e.classList.contains("revealed")?"المعنى بالعربية":"اضغط لإظهار المعنى"}
function known(w){if(!db.known.includes(w)){db.known.push(w);db.points+=2}db.review.push(w);save();toast("تمت إضافة الكلمة إلى قائمة المراجعة");vocabPage()}
function reviewPage(){title("المراجعة الذكية");let list=allWords.filter(x=>db.review.includes(x.word)||!db.known.includes(x.word)).slice(0,18);$("#content").innerHTML=`<p class="page-intro">راجع الكلمات التي لم تتقنها بعد. المراجعة المتكررة تساعد على تثبيت الذاكرة.</p><div class="metric-grid"><div class="metric"><b>${db.known.length}</b><small>كلمات أتقنتها</small></div><div class="metric"><b>${allWords.length-db.known.length}</b><small>كلمات تحتاج مراجعة</small></div><div class="metric"><b>${db.review.length}</b><small>إضافات للمراجعة</small></div></div><div class="section-head"><h3>قائمة المراجعة</h3><small>مجموعة من مفرداتك</small></div><div class="lesson-list">${list.slice(0,12).map((v,i)=>`<div class="lesson"><div class="lesson-num">${i+1}</div><div><b dir="auto">${v.word}</b><small>${v.flag} ${v.meaning}</small></div><button class="btn ghost" onclick="speak('${v.word}','${v.id}')">🔊 نطق</button></div>`).join("")}</div>`}
function progressPage(){title("تقارير التقدم");let total=LANGS.reduce((n,l)=>n+l.units.length*6,0),pctAll=Math.round(db.done.length/total*100);$("#content").innerHTML=`<p class="page-intro">تابع إنجازاتك ونشاطك في تعلم اللغات الأربع.</p><div class="metric-grid"><div class="metric"><b>${db.done.length}</b><small>دروس مكتملة</small></div><div class="metric"><b>${db.points}</b><small>نقطة مكتسبة</small></div><div class="metric"><b>${db.minutes}</b><small>دقيقة تعلم مسجلة</small></div><div class="metric"><b>${unitQuizStats().n}</b><small>اختبارات وحدات · متوسط ${unitQuizStats().avg}%</small></div></div><div class="panel" style="margin-top:15px"><h3>الإنجاز الكلي</h3><div style="font-size:30px;color:var(--purple);font-weight:800">${pctAll}%</div><div class="track"><span style="width:${pctAll}%"></span></div><p class="subtext">يتم احتساب الإنجاز وفق ${LANGS[0].units.length*6} وحدة لكل لغة.</p></div><div class="section-head"><h3>تفاصيل اللغات</h3></div><div class="language-grid">${LANGS.map(l=>`<div class="language-card"><span class="flag">${l.flag}</span><h3>${l.name}</h3><div style="font-size:22px;color:var(--purple);font-weight:800">${pct(l.id)}%</div><div class="track"><span style="width:${pct(l.id)}%;background:${l.color}"></span></div><small class="subtext">${doneCount(l.id)} درس مسجل · ${db.level[l.id]}</small></div>`).join("")}</div><div style="margin-top:17px"><button class="btn ghost" onclick="if(confirm('هل تريد حذف تقدمك بالكامل؟')){db={done:[],known:[],points:0,minutes:0,level:{es:'A1',ru:'A1',fr:'A1',de:'A1'},active:'es',review:[],quizCorrect:0,unitQuiz:{},placement:{},badges:[],listenCorrect:0,streakDays:1,lastDay:null,storiesRead:[],speakCorrect:0,daily:{}};save();progressPage()}">إعادة ضبط التقدم</button></div>`}
function tutorPage(){title("المدرس الذكي");$("#content").innerHTML=`<p class="page-intro">مدرس ذكي حقيقي يشرح لك المفردات والقواعد، يصحح جملك، ويتحدث معك بمستواك. اسأله أي شيء عن اللغة.</p><div class="tutor-box"><div class="card-foot"><b>✦ Polyglot AI Tutor</b><span>${LANGS.find(l=>l.id===lang).flag} ${LANGS.find(l=>l.id===lang).name}</span></div><div class="tabs" style="margin-top:13px">${LANGS.map(l=>`<button class="tab ${lang===l.id?"active":""}" onclick="lang='${l.id}';tutorPage()">${l.flag} ${l.name}</button>`).join("")}</div><div class="chat-log" id="chat"></div><div class="chat-input"><input id="chatInput" placeholder="اكتب سؤالك هنا..." onkeydown="if(event.key==='Enter')sendChat()"><button class="btn" onclick="sendChat()">إرسال</button></div><div class="center-actions" style="margin-top:12px"><button class="tab" onclick="quickAsk('اختبرني في المفردات')">اختبرني</button><button class="tab" onclick="quickAsk('اشرح لي قاعدة أساسية')">اشرح قاعدة</button><button class="tab" onclick="quickAsk('أريد محادثة للمبتدئين')">تدرب على المحادثة</button><button class="tab" onclick="clearChat()">🗑 محادثة جديدة</button></div></div>`;renderChat()}
const AI_URL="https://studyflow-ai.ym6642909.workers.dev/chat/completions",AI_MODEL="gemini-3.5-flash-lite";
let chatHist=JSON.parse(localStorage.getItem("polyglot-chats")||"{}");
function saveChats(){for(const k in chatHist)chatHist[k]=chatHist[k].slice(-24);localStorage.setItem("polyglot-chats",JSON.stringify(chatHist))}
function renderChat(){let c=$("#chat");if(!c)return;let l=LANGS.find(x=>x.id===lang),h=chatHist[lang]||[];c.innerHTML="";if(!h.length){addBubble("مرحباً! أنا مساعدك التعليمي، وأفتكر محادثتنا حتى لو قفلت الصفحة. اسألني عن معنى كلمة، اطلب تدريباً، أو اكتب لي جملة بـ"+l.name+" وأنا أصححها لك.","ai")}else{h.forEach(m=>{let d=addBubble(m.content,m.role==="user"?"user":"ai");if(m.role!=="user")d.innerHTML=mdLite(m.content)})}c.scrollTop=c.scrollHeight}
function clearChat(){chatHist[lang]=[];saveChats();renderChat();toast("بدأنا محادثة جديدة في "+LANGS.find(x=>x.id===lang).name)}
function mdInline(t){return t.replace(/`([^`]+)`/g,"<code>$1</code>").replace(/\*\*([^*]+)\*\*/g,"<strong>$1</strong>").replace(/__([^_]+)__/g,"<strong>$1</strong>").replace(/(^|[\s(>])\*([^*\s][^*]*?)\*(?=[\s).,:;!?؟،]|$)/g,"$1<em>$2</em>")}
function mdLite(t){let esc=t.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/\r/g,""),L=esc.split("\n"),o="",i=0,list=null;
function close(){if(list){o+="</"+list+">";list=null}}
while(i<L.length){let ln=L[i],tr=ln.trim();
if(!tr){close();i++;continue}
if(/^([-*_])(\s*\1){2,}$/.test(tr)){close();o+="<hr>";i++;continue}
let h=tr.match(/^(#{1,6})\s+(.*)$/);if(h){close();o+="<h4>"+mdInline(h[2])+"</h4>";i++;continue}
if(tr.indexOf("|")>-1&&L[i+1]&&/^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$/.test(L[i+1])){close();let cells=r=>r.trim().replace(/^\||\|$/g,"").split("|").map(c=>mdInline(c.trim()));let hd=cells(tr);o+='<div class="tbl-wrap"><table class="md-table"><tr>'+hd.map(c=>"<th>"+c+"</th>").join("")+"</tr>";i+=2;while(i<L.length&&L[i].indexOf("|")>-1&&L[i].trim()){o+="<tr>"+cells(L[i]).map(c=>"<td>"+c+"</td>").join("")+"</tr>";i++}o+="</table></div>";continue}
let b=tr.match(/^[*\-•]\s+(.*)$/),n=tr.match(/^\d+[.)]\s+(.*)$/);
if(b){if(list!=="ul"){close();o+="<ul>";list="ul"}o+="<li>"+mdInline(b[1])+"</li>";i++;continue}
if(n){if(list!=="ol"){close();o+="<ol>";list="ol"}o+="<li>"+mdInline(n[1])+"</li>";i++;continue}
close();o+="<p>"+mdInline(tr)+"</p>";i++}
close();return o}
async function sendChat(){let input=$("#chatInput"),s=input.value.trim();if(!s||window.chatBusy)return;addBubble(s,"user");input.value="";let l=LANGS.find(x=>x.id===lang),h=chatHist[lang]=chatHist[lang]||[];h.push({role:"user",content:s});saveChats();window.chatBusy=true;let wait=addBubble("...","ai");
let sys=`أنت "Polyglot AI Tutor"، مدرس لغات ودود لطالب عربي يتعلم ${l.name} (${l.native}) في مستوى ${db.level[lang]}. اشرح بالعربية، وأعطِ الأمثلة بـ${l.name} مع الترجمة العربية والنطق بالحروف العربية عند الحاجة. اجعل الردود قصيرة وواضحة، واطرح سؤال تدريب صغيراً في النهاية. إذا كتب الطالب جملة بـ${l.name} فصححها أولاً: اعرض **الجملة الصحيحة** ثم اشرح الخطأ في سطر واحد (قاعدة، إملاء، أو ترتيب كلمات)، وبعدها أكمل الحوار بجملة جديدة مناسبة لمستواه. اعتمد على سياق محادثتكما السابقة ولا تكرر نفس التصحيح. استخدم تنسيق ماركداون بسيطاً (عناوين قصيرة، قوائم نقطية، **خط عريض**، وجداول عند الحاجة) ولا تستعمل الخطوط الفاصلة ---. إذا طلب محادثة فتحدث ${l.name} بجمل بسيطة ثم ترجم.`;
try{let r=await fetch(AI_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:AI_MODEL,messages:[{role:"system",content:sys}].concat(h.slice(-12))})});if(r.status===429)throw new Error("limit");if(!r.ok)throw new Error("http");let j=await r.json(),t=j.choices&&j.choices[0]&&j.choices[0].message.content;if(!t)throw new Error("empty");h.push({role:"assistant",content:t});saveChats();wait.innerHTML=mdLite(t);db.points+=1;save()}catch(e){h.pop();wait.textContent=e.message==="limit"?"وصلت للحد الأقصى من الرسائل حالياً. جرّب بعد قليل.":"تعذر الاتصال بالمدرس الآن. تأكد من الإنترنت وحاول مرة أخرى."}
window.chatBusy=false;let c=$("#chat");if(c)c.scrollTop=c.scrollHeight}
function addBubble(t,who){let c=$("#chat");if(!c)return;let d=document.createElement("div");d.className="bubble "+who;d.textContent=t;c.appendChild(d);c.scrollTop=c.scrollHeight;return d}
function quickAsk(t){$("#chatInput").value=t;sendChat()}
document.querySelectorAll(".nav").forEach(n=>n.addEventListener("click",()=>go(n.dataset.page)));
$("#menuBtn").addEventListener("click",()=>$("#sidebar").classList.toggle("open"));
$("#goalBtn").addEventListener("click",()=>toast("هدف اليوم: درس واحد + 5 كلمات + اختبار قصير 🎯"));
$("#settingsBtn").addEventListener("click",()=>toast("إعدادات الحساب والمزامنة السحابية متاحة في مرحلة الربط بالخادم."));
function finishUnitQuiz(){let{id,i}=quiz.unit,l=LANGS.find(x=>x.id===id),key=id+"-"+db.level[id]+"-"+i,sc=quiz.score,tot=quiz.length,pass=sc>=3,first=false;if(db.unitQuiz[key]==null||sc>db.unitQuiz[key])db.unitQuiz[key]=sc;if(pass&&!db.done.includes(key)){db.done.push(key);db.points+=25;db.minutes+=10;first=true}db.minutes+=3;save();
$("#quiz").innerHTML=`<div class="empty"><div style="font-size:40px">${sc===tot?"🏆":pass?"🎉":"💪"}</div><h2>${l.units[i][0]}: ${sc} من ${tot}</h2><p>${sc===tot?"نتيجة كاملة! ممتاز.":pass?"أحسنت! اجتزت اختبار الوحدة.":"حاول مرة أخرى بعد مراجعة الدرس. تحتاج 3 من 5 للنجاح."}</p><p class="subtext">حصلت على ${sc*10} نقطة من الإجابات${first?" + 25 نقطة لإكمال الوحدة":""}</p><div class="center-actions"><button class="btn" onclick="startUnitQuiz('${id}',${i})">إعادة الاختبار</button><button class="btn ghost" onclick="lesson('${id}',${i})">مراجعة الدرس</button><button class="btn ghost" onclick="openLang('${id}')">← الوحدات</button></div></div>`}
function unitQuizStats(){let v=Object.values(db.unitQuiz||{});return{n:v.length,avg:v.length?Math.round(v.reduce((a,b)=>a+b,0)/v.length/5*100):0}}

/* ===== Round 4: placement test, listening dictation, achievements ===== */
function placeHome(){let l=LANGS.find(x=>x.id===lang),p=db.placement&&db.placement[lang];$("#prac").innerHTML=`<div class="quiz-box"><div class="empty"><div style="font-size:36px">🧭</div><b>اختبار تحديد المستوى · ${l.name}</b><p class="subtext" style="margin:10px 0">12 سؤالاً بصعوبة متزايدة تغطي وحدات اللغة كلها. في النهاية نحدد مستواك (A1 - C2) وأفضل وحدة تبدأ منها.</p>${p?`<p class="subtext">آخر نتيجة لك: ${p.score}/12 · المستوى ${p.level} · تبدأ من الوحدة ${p.unit}</p>`:""}<button class="btn" onclick="startPlacement()">ابدأ اختبار تحديد المستوى</button></div></div>`}
function startPlacement(){let l=LANGS.find(x=>x.id===lang);quiz=l.units.map((u,i)=>{let g=GRAMMAR[l.id]&&GRAMMAR[l.id][i],t=i%3,oth=l.units.filter((_,k)=>k!==i),fo=oth.flatMap(x=>[x[1],x[3]]),ar=oth.flatMap(x=>[x[2],x[4]]);
let mk=(q,a,pool,label,isAr)=>({q,a,label,ar:isAr,lid:l.id,opts:sh([a].concat(sh(pool.filter(x=>x!==a)).slice(0,2)))});
if(t===2&&g)return{q:g[4][0],a:g[4][1],label:"سؤال قاعدة · الوحدة "+(i+1)+" من 12 · "+g[0],ar:true,opts:sh(g[4].slice(1))};
if(t===1)return mk(u[4],u[3],fo,"كيف تقولها بـ"+l.name+"؟ · الوحدة "+(i+1)+" من 12",true);
return mk(u[1],u[2],ar,"ما معنى هذه العبارة؟ · الوحدة "+(i+1)+" من 12",false)});
quiz.placement={id:l.id};$("#prac").innerHTML='<div class="quiz-box" id="quiz"></div>';qi=0;quiz.score=0;showQ()}
function finishPlacement(){let id=quiz.placement.id,sc=quiz.score,lv=sc<=3?"A1":sc<=5?"A2":sc<=7?"B1":sc<=9?"B2":sc<=11?"C1":"C2",rec=Math.min(sc+1,12),l=LANGS.find(x=>x.id===id);
db.level[id]=lv;db.placement=db.placement||{};db.placement[id]={score:sc,level:lv,unit:rec,when:Date.now()};db.minutes+=5;save();
$("#quiz").innerHTML=`<div class="empty"><div style="font-size:40px">🧭</div><h2>مستواك في ${l.name}: ${lv}</h2><p>أجبت على ${sc} من 12 سؤالاً. ننصحك أن تبدأ من الوحدة ${rec}: «${l.units[rec-1][0]}»</p><p class="subtext">تم تحديث شارة مستواك · +${sc*10} نقطة من الإجابات الصحيحة</p><div class="center-actions"><button class="btn" onclick="go('languages');openLang('${id}');lesson('${id}',${rec-1})">ابدأ من الوحدة ${rec} ←</button><button class="btn ghost" onclick="startPlacement()">إعادة الاختبار</button><button class="btn ghost" onclick="practicePage()">التمارين</button></div></div>`}

let lisPick=[],lisI=0,lisScore=0;
function listenHome(){let l=LANGS.find(x=>x.id===lang);$("#prac").innerHTML=`<div class="quiz-box"><div class="empty"><div style="font-size:36px">🎧</div><b>تمارين الاستماع · ${l.name}</b><p class="subtext" style="margin:10px 0">استمع إلى الجملة ثم اكتب ما سمعته. التصحيح يتجاهل الحروف الكبيرة وعلامات الترقيم ولهجات الحروف.</p><p class="subtext">إجاباتك الصحيحة حتى الآن: ${db.listenCorrect||0}</p><button class="btn" onclick="startListening()">ابدأ التمرين · 5 جمل</button></div></div>`}
function startListening(){let l=LANGS.find(x=>x.id===lang),all=l.units.flatMap(u=>[[u[1],u[2]],[u[3],u[4]]]);lisPick=sh(all).slice(0,5);lisI=0;lisScore=0;showListen()}
function showListen(){if(lisI>=lisPick.length){$("#prac").innerHTML=`<div class="quiz-box"><div class="empty"><div style="font-size:40px">${lisScore>=4?"🏆":"🎧"}</div><h2>انتهى التمرين!</h2><p>نتيجتك: ${lisScore} من ${lisPick.length}</p><p class="subtext">+${lisScore*10} نقطة</p><div class="center-actions"><button class="btn" onclick="startListening()">تمرين جديد</button><button class="btn ghost" onclick="practicePage()">التمارين</button></div></div></div>`;return}
$("#prac").innerHTML=`<div class="quiz-box"><div class="card-foot"><span>🎧 تمرين الاستماع · الجملة ${lisI+1} من ${lisPick.length}</span><span>⭐ ${db.points} نقطة</span></div><div class="track"><span style="width:${lisI/lisPick.length*100}%"></span></div><div class="question">استمع إلى الجملة ثم اكتبها</div><div class="center-actions" style="margin:16px 0"><button class="btn dark" onclick="speak(lisPick[lisI][0],lang)">🔊 استمع</button><button class="btn ghost" onclick="speak(lisPick[lisI][0],lang)">↻ إعادة الاستماع</button></div><div class="chat-input"><input id="lisIn" dir="auto" placeholder="اكتب الجملة التي سمعتها..." autocomplete="off" onkeydown="if(event.key==='Enter')checkListen()"><button class="btn" onclick="checkListen()">تحقق</button></div><div class="feedback" id="lisFb"></div><div class="center-actions" style="margin-top:10px"><button class="btn" id="lisNext" style="display:none" onclick="lisI++;showListen()">التالي ←</button></div></div>`;
setTimeout(()=>speak(lisPick[lisI][0],lang),350);let inp=$("#lisIn");if(inp)inp.focus()}
function normLis(t){return (t||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/ß/g,"ss").replace(/[^a-zа-яё0-9\s]/g,"").replace(/\s+/g,"")}
function checkListen(){let s=lisPick[lisI],inp=$("#lisIn"),v=inp.value,ok=normLis(v)===normLis(s[0]),fb=$("#lisFb");inp.disabled=true;
if(ok){lisScore++;db.points+=10;db.listenCorrect=(db.listenCorrect||0)+1;db.minutes+=1;fb.innerHTML=`✅ إجابة صحيحة! +10 نقاط<br><b dir="ltr">${s[0]}</b><br><small>${s[1]}</small>`}
else{fb.innerHTML=`❌ الجملة الصحيحة:<br><b dir="ltr">${s[0]}</b> <button class="icon-btn sm" onclick="speak(lisPick[lisI][0],lang)">🔊</button><br><small>${s[1]}</small>${v.trim()?`<br><small class="subtext">كتبت: ${v.replace(/&/g,"&amp;").replace(/</g,"&lt;")}</small>`:""}`}
save();$("#lisNext").style.display="inline-block"}

