let spkPick=[],spkI=0,spkScore=0,spkRec=null;
function srSupport(){return window.SpeechRecognition||window.webkitSpeechRecognition||null}
function speakHome(){let l=LANGS.find(x=>x.id===lang),ok=srSupport();
$("#prac").innerHTML=`<div class="quiz-box"><div class="empty"><div style="font-size:36px">🎤</div><b>تمرين الكلام · ${l.name}</b><p class="subtext" style="margin:10px 0">اقرأ الجملة المعروضة بصوت واضح، والموقع يقارن نطقك بالجملة الصحيحة ويعطيك درجة من 100.</p>${ok?`<p class="subtext">نطقاتك الصحيحة حتى الآن: ${db.speakCorrect||0}</p><button class="btn" onclick="startSpeaking()">ابدأ التمرين · 5 جمل</button>`:`<div class="note">متصفحك الحالي لا يدعم التعرف على الصوت. جرّب Google Chrome على الهاتف أو الكمبيوتر، واسمح للموقع باستخدام الميكروفون.</div>`}</div></div>`}
function startSpeaking(){let l=LANGS.find(x=>x.id===lang),all=l.units.flatMap(u=>[[u[1],u[2]],[u[3],u[4]]]);spkPick=sh(all).slice(0,5);spkI=0;spkScore=0;showSpeak()}
function showSpeak(){if(spkI>=spkPick.length){$("#prac").innerHTML=`<div class="quiz-box"><div class="empty"><div style="font-size:40px">${spkScore>=4?"🏆":"🎤"}</div><h2>انتهى التمرين!</h2><p>نطق صحيح: ${spkScore} من ${spkPick.length}</p><div class="center-actions"><button class="btn" onclick="startSpeaking()">تمرين جديد</button><button class="btn ghost" onclick="practicePage()">التمارين</button></div></div></div>`;return}
$("#prac").innerHTML=`<div class="quiz-box"><div class="card-foot"><span>🎤 تمرين الكلام · الجملة ${spkI+1} من ${spkPick.length}</span><span>⭐ ${db.points} نقطة</span></div><div class="track"><span style="width:${spkI/spkPick.length*100}%"></span></div><div class="question">اقرأ هذه الجملة بصوت واضح</div><div class="foreign" dir="ltr">${spkPick[spkI][0]} <button class="icon-btn sm" onclick="speak(spkPick[spkI][0],lang)">🔊</button></div><p class="subtext" style="text-align:center">${spkPick[spkI][1]}</p><div class="center-actions" style="margin:14px 0"><button class="btn dark" id="micBtn" onclick="recog()">🎤 ابدأ التحدث</button></div><div class="feedback" id="spkFb"></div><div class="center-actions" style="margin-top:10px"><button class="btn" id="spkNext" style="display:none" onclick="spkI++;showSpeak()">التالي ←</button> <button class="btn ghost" onclick="spkI++;showSpeak()">تخطي</button></div></div>`}
function simScore(said,target){let w=t=>normLis(t).split(" ").filter(Boolean),a=w(said),b=w(target);if(!b.length)return 0;let pool=b.slice(),hit=0;a.forEach(x=>{let i=pool.indexOf(x);if(i>-1){pool.splice(i,1);hit++}});return Math.round(hit/b.length*100)}
function recog(){let SR=srSupport();if(!SR){toast("التعرف على الصوت غير مدعوم في هذا المتصفح");return}
if(spkRec){try{spkRec.stop()}catch(e){}return}
let l=LANGS.find(x=>x.id===lang),r=new SR();spkRec=r;r.lang=l.voice;r.interimResults=false;r.maxAlternatives=3;
let btn=$("#micBtn"),fb=$("#spkFb");btn.textContent="🔴 استمع إليك... تحدث الآن";btn.classList.add("rec");
r.onresult=e=>{let said="";for(let i=0;i<e.results[0].length;i++){let alt=e.results[0][i].transcript;if(simScore(alt,spkPick[spkI][0])>simScore(said,spkPick[spkI][0]))said=alt}
let sc=simScore(said,spkPick[spkI][0]),s=spkPick[spkI][0],pts=sc>=85?15:sc>=60?10:sc>=40?3:0;
if(sc>=60){spkScore++;db.speakCorrect=(db.speakCorrect||0)+1}
if(pts){db.points+=pts;db.minutes+=1;save()}
fb.innerHTML=`${sc>=85?"🌟 نطق ممتاز!":sc>=60?"✅ نطق جيد!":sc>=40?"🔄 قريب، حاول مرة أخرى":"❌ لم يطابق الجملة"} درجتك: ${sc}/100${pts?" · +"+pts+" نقطة":""}<br><b dir="ltr">${s}</b> <button class="icon-btn sm" onclick="speak(spkPick[spkI][0],lang)">🔊</button><br><small>${s&&spkPick[spkI][1]}</small>${said?`<br><small class="subtext">سمعتك تقول: ${said.replace(/&/g,"&amp;").replace(/</g,"&lt;")}</small>`:""}`;
$("#spkNext").style.display="inline-block";endRec(btn)};
r.onerror=e=>{endRec(btn);fb.textContent=e.error==="not-allowed"?"اسمح للموقع باستخدام الميكروفون من إعدادات المتصفح ثم حاول مرة أخرى.":"لم أسمعك جيداً. اضغط الميكروفون وحاول مرة أخرى."};
r.onend=()=>endRec(btn);
try{r.start()}catch(e){endRec(btn)}}
function endRec(btn){spkRec=null;if(btn){btn.textContent="🎤 حاول مرة أخرى";btn.classList.remove("rec")}}

let storyLang=db.active||"es";
function storiesPage(){title("قصص قصيرة");let list=STORIES[storyLang]||STORIES.es;
$("#content").innerHTML=`<p class="page-intro">قصص قصيرة بمستويات مختلفة. اضغط على أي جملة لإظهار ترجمتها، واستمع إلى القصة كاملة بصوت واضح.</p><div class="tabs">${LANGS.map(l=>`<button class="tab ${storyLang===l.id?"active":""}" onclick="storyLang='${l.id}';storiesPage()">${l.flag} ${l.name}</button>`).join("")}</div><div class="lesson-list">${list.map((st,i)=>{let key=storyLang+"-"+i,rd=(db.storiesRead||[]).indexOf(key)>-1;return `<div class="lesson"><div class="lesson-num">${st.level}</div><div><b>${st.title}</b><small>${st.s.length} جمل · مستوى ${st.level}${rd?" · ✅ قرأتها":""}</small></div><button class="btn ${rd?"ghost":""}" onclick="readStory(${i})">${rd?"إعادة القراءة":"اقرأ القصة"}</button></div>`}).join("")}</div><div id="storyBox"></div>`}
function readStory(i){let st=STORIES[storyLang][i],key=storyLang+"-"+i,rd=(db.storiesRead||[]).indexOf(key)>-1;
$("#storyBox").innerHTML=`<div class="panel story" style="margin-top:15px"><div class="card-foot"><h3 style="margin:0">${LANGS.find(l=>l.id===storyLang).flag} ${st.title}</h3><span class="tag">${st.level}</span></div><p class="subtext">اضغط على الجملة لإظهار الترجمة أو إخفائها</p>${st.s.map((sn,k)=>`<div class="story-line" onclick="this.classList.toggle('open')"><p dir="ltr"><b>${sn[0]}</b> <button class="icon-btn sm" onclick="event.stopPropagation();speak(STORIES['${storyLang}'][${i}].s[${k}][0],'${storyLang}')">🔊</button></p><small class="story-ar">${sn[1]}</small></div>`).join("")}<div class="center-actions" style="margin-top:14px"><button class="btn dark" onclick="speakStory(${i})">🔊 استمع إلى القصة كاملة</button>${rd?"":`<button class="btn" onclick="finishStory(${i})">أنهيت القصة ✓ (+15 نقطة)</button>`}</div></div>`;
$("#storyBox").scrollIntoView({behavior:"smooth",block:"start"})}
function finishStory(i){let key=storyLang+"-"+i;if((db.storiesRead||[]).indexOf(key)<0){db.storiesRead.push(key);db.points+=15;db.minutes+=5;save();toast("أحسنت! +15 نقطة لإكمال القصة 📖")}readStory(i)}
function speakStory(i){if(!("speechSynthesis"in window)){toast("النطق غير مدعوم في هذا المتصفح");return}speechSynthesis.cancel();
let st=STORIES[storyLang][i],l=LANGS.find(x=>x.id===storyLang),vs=speechSynthesis.getVoices(),v=vs.find(x=>x.lang===l.voice)||vs.find(x=>x.lang&&x.lang.toLowerCase().startsWith(l.voice.slice(0,2).toLowerCase()));
let k=0;function next(){if(k>=st.s.length)return;let u=new SpeechSynthesisUtterance(st.s[k][0]);u.lang=l.voice;u.rate=.9;if(v)u.voice=v;u.onend=()=>{k++;next()};speechSynthesis.speak(u)}next()}

function weekChart(){db.daily=db.daily||{};let days=[],now=Date.now(),names=["أحد","اثنين","ثلاثاء","أربعاء","خميس","جمعة","سبت"];
for(let i=6;i>=0;i--){let d=new Date(now-i*864e5);days.push({v:db.daily[d.toDateString()]||0,w:names[d.getDay()],today:i===0})}
let mx=Math.max(20,...days.map(d=>d.v)),W=420,H=140,bw=26,gap=(W-20)/7;
let bars=days.map((d,i)=>{let h=Math.round(d.v/mx*95),x=10+i*gap+(gap-bw)/2,y=105-h;return `<rect x="${x}" y="${y}" width="${bw}" height="${h}" rx="5" style="fill:var(--chart-${d.today?"today":"bar"})"></rect><text x="${x+bw/2}" y="${y-5}" text-anchor="middle" font-size="10" font-weight="700" style="fill:var(--chart-${d.v?"num":"num0"})">${d.v||""}</text><text x="${x+bw/2}" y="122" text-anchor="middle" font-size="9" style="fill:var(--chart-${d.today?"num":"day"})" font-weight="${d.today?"700":"400"}">${d.w}</text>`}).join("");
return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;max-width:560px;display:block;margin:8px auto 0" dir="ltr"><line x1="10" y1="105" x2="${W-10}" y2="105" style="stroke:var(--chart-line)" stroke-width="1.5"/>${bars}</svg>`}

/* ===== Round 6: daily challenge, role-play, dark mode ===== */
db.dailyCh=db.dailyCh||{};db.roleplayDone=db.roleplayDone||[];db.verbCorrect=db.verbCorrect||0;db.writeCount=db.writeCount||0;
function seedRnd(str){let h=2166136261;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}return function(){h=(Math.imul(h^(h>>>13),1103515245)+12345)|0;h^=h>>>16;return(h>>>0)/4294967296}}
function shS(a,r){a=a.slice();for(let i=a.length-1;i>0;i--){let j=Math.floor(r()*(i+1)),t=a[i];a[i]=a[j];a[j]=t}return a}
function dailyKey(){return lang+"|"+new Date().toDateString()}
function dailyLeft(){let n=new Date(),m=new Date(n);m.setHours(24,0,0,0);let s=Math.max(0,Math.floor((m-n)/1000));return Math.floor(s/3600)+" ساعة و"+Math.floor(s%3600/60)+" دقيقة"}
function dailyHome(){let l=LANGS.find(x=>x.id===lang),d=db.dailyCh[dailyKey()],n=Object.keys(db.dailyCh).length;
$("#prac").innerHTML=`<div class="quiz-box"><div class="empty"><div style="font-size:36px">🎯</div><b>تحدي اليوم · ${l.name}</b>${d?`<p class="subtext" style="margin:10px 0">أنجزت تحدي اليوم! نتيجتك: ${d.score} من ${d.total} ✅</p><p class="subtext">التحدي القادم بعد ${dailyLeft()}</p><button class="btn ghost" onclick="practicePage()">تمارين أخرى</button>`:`<p class="subtext" style="margin:10px 0">8 أسئلة متنوعة (مفردات وترجمة وقواعد) تتجدد كل يوم. أكمل التحدي واكسب مكافأة <b>+50 نقطة</b> إضافية!</p>${n?`<p class="subtext">تحديات أكملتها حتى الآن: ${n}</p>`:""}<button class="btn" onclick="startDaily()">ابدأ تحدي اليوم</button>`}</div></div>`}
function startDaily(){let l=LANGS.find(x=>x.id===lang),r=seedRnd(dailyKey()),all=l.units.flatMap(u=>[[u[1],u[2]],[u[3],u[4]]]),pick=shS(all,r).slice(0,6),fo=all.map(x=>x[0]),ar=all.map(x=>x[1]);
let mk=(q,a,pool,label,isAr)=>({q,a,label,ar:isAr,lid:l.id,opts:shS([a].concat(shS(pool.filter(x=>x!==a),r).slice(0,2)),r)});
quiz=pick.slice(0,3).map(p=>mk(p[0],p[1],ar,"ما معنى هذه العبارة؟",false)).concat(pick.slice(3).map(p=>mk(p[1],p[0],fo,"كيف تقولها بـ"+l.name+"؟",true)));
let gi=shS(l.units.map((_,i)=>i).filter(i=>GRAMMAR[l.id]&&GRAMMAR[l.id][i]),r).slice(0,2);
gi.forEach(i=>{let g=GRAMMAR[l.id][i];quiz.push({q:g[4][0],a:g[4][1],label:"سؤال قاعدة · "+g[0],ar:true,opts:shS(g[4].slice(1),r)})});
quiz.daily={id:l.id};$("#prac").innerHTML='<div class="quiz-box" id="quiz"></div>';qi=0;quiz.score=0;showQ()}
function finishDaily(){let sc=quiz.score,tot=quiz.length;db.dailyCh[dailyKey()]={score:sc,total:tot};db.points+=50;db.minutes+=5;save();
$("#quiz").innerHTML=`<div class="empty"><div style="font-size:40px">${sc>=6?"🏆":"🎯"}</div><h2>أنجزت تحدي اليوم!</h2><p>نتيجتك: ${sc} من ${tot}</p><p class="subtext">+${sc*10} نقطة من الإجابات + 50 نقطة مكافأة التحدي ⭐</p><p class="subtext">عد غداً لتحدٍ جديد · التحدي القادم بعد ${dailyLeft()}</p><div class="center-actions"><button class="btn" onclick="practicePage()">تمارين أخرى</button><button class="btn ghost" onclick="go('dashboard')">الرئيسية</button></div></div>`}
BADGES.push(
{id:"daily-win",icon:"🎯",name:"محارب اليوم",desc:"أكمل تحدي اليوم مرة واحدة",test:()=>Object.keys(db.dailyCh||{}).length>=1},
{id:"daily-7",icon:"📅",name:"عادة يومية",desc:"أكمل تحدي اليوم 7 مرات",test:()=>Object.keys(db.dailyCh||{}).length>=7},
{id:"rp-1",icon:"🎭",name:"ممثل المواقف",desc:"أكمل محادثة موقف كاملة مع المدرس",test:()=>(db.roleplayDone||[]).length>=1});
function applyTheme(){let d=localStorage.getItem("polyglot-theme")==="dark";document.body.classList.toggle("dark",d);let b=$("#themeBtn");if(b)b.textContent=d?"☀️":"🌙";let m=document.querySelector('meta[name="theme-color"]');if(m)m.content=d?"#0e1526":"#10172b"}
$("#themeBtn").addEventListener("click",()=>{localStorage.setItem("polyglot-theme",localStorage.getItem("polyglot-theme")==="dark"?"light":"dark");applyTheme();toast(localStorage.getItem("polyglot-theme")==="dark"?"الوضع الليلي مفعّل 🌙":"الوضع النهاري مفعّل ☀️")});
applyTheme();

