function startRP(id){rp=RP_SCENARIOS.find(s=>s.id===id);let k=rpKey();chatHist[k]=chatHist[k]||[];tutorPage();if(!chatHist[k].length){chatHist[k].push({role:"user",content:"(ابدأ المشهد الآن: رحّب بالطالب في دورك وابدأ المحادثة بجملة أولى قصيرة)",hidden:true});rpSend(null)}}
function endRP(){rp=null;tutorPage()}
function rpPrompt(l){return `أنت تلعب دور "${rp.role}" في تدريب محادثة واقعية مع طالب عربي يتعلم ${l.name} (${l.native}) بمستوى ${db.level[lang]}. التزم بدورك طوال المشهد ولا تخرج منه. تحدث بـ${l.name} بجمل قصيرة وبسيطة مناسبة لمستواه، وبعد كل جملة منك ضع ترجمتها العربية بين قوسين. إذا أخطأ الطالب في جملته فصححها أولاً في سطر واحد بالعربية: اعرض **الجملة الصحيحة** ثم سبب الخطأ باختصار، وبعدها أكمل المشهد بردك في الدور. شجعه بلطف وقود الحوار بأسئلة طبيعية يطرحها شخص في موقعك (${rp.name}). اجعل ردودك قصيرة: التصحيح إن وجد ثم جملة أو جملتان في الدور. لا تستعمل الخطوط الفاصلة ---.`}
function tutorPrompt(l){return `أنت "Polyglot AI Tutor"، مدرس لغات ودود لطالب عربي يتعلم ${l.name} (${l.native}) في مستوى ${db.level[lang]}. اشرح بالعربية، وأعطِ الأمثلة بـ${l.name} مع الترجمة العربية والنطق بالحروف العربية عند الحاجة. اجعل الردود قصيرة وواضحة، واطرح سؤال تدريب صغيراً في النهاية. إذا كتب الطالب جملة بـ${l.name} فصححها أولاً: اعرض **الجملة الصحيحة** ثم اشرح الخطأ في سطر واحد (قاعدة، إملاء، أو ترتيب كلمات)، وبعدها أكمل الحوار بجملة جديدة مناسبة لمستواه. اعتمد على سياق محادثتكما السابقة ولا تكرر نفس التصحيح. استخدم تنسيق ماركداون بسيطاً (عناوين قصيرة، قوائم نقطية، **خط عريض**، وجداول عند الحاجة) ولا تستعمل الخطوط الفاصلة ---. إذا طلب محادثة فتحدث ${l.name} بجمل بسيطة ثم ترجم.`}
function tutorPage(){title("المدرس الذكي");let done=(db.roleplayDone||[]);
$("#content").innerHTML=`<p class="page-intro">مدرس ذكي حقيقي يشرح لك المفردات والقواعد، يصحح جملك، ويتحدث معك بمستواك. اسأله أي شيء عن اللغة.</p><div class="tutor-box"><div class="card-foot"><b>✦ Polyglot AI Tutor</b><span>${LANGS.find(l=>l.id===lang).flag} ${LANGS.find(l=>l.id===lang).name}</span></div><div class="tabs" style="margin-top:13px">${LANGS.map(l=>`<button class="tab ${lang===l.id?"active":""}" onclick="lang='${l.id}';tutorPage()">${l.flag} ${l.name}</button>`).join("")}</div>${rp?`<div class="note" style="display:flex;align-items:center;gap:9px;margin-top:12px;margin-bottom:0"><span style="font-size:20px">${rp.icon}</span><div style="flex:1"><b>موقف: ${rp.name}</b><br><small>تحدث بـ${LANGS.find(l=>l.id===lang).name} والمدرس يلعب دور "${rp.role}" ويصحح لك بالعربية</small></div><button class="btn ghost" onclick="endRP()">إنهاء الموقف</button></div>`:`<div class="section-head" style="margin-top:16px"><h3>🎭 محادثات مواقف حقيقية</h3><small>تدرب على موقف كامل مع المدرس</small></div><div class="rp-grid">${RP_SCENARIOS.map(s=>`<button class="rp-card" onclick="startRP('${s.id}')"><span class="rp-icon">${s.icon}</span><b>${s.name}</b><small>${s.desc}</small>${done.indexOf(lang+"::rp::"+s.id)>-1?'<span class="rp-done">✓ مكتمل</span>':""}</button>`).join("")}</div>`}<div class="chat-log" id="chat"></div><div class="chat-input"><input id="chatInput" placeholder="${rp?"اكتب ردك في الموقف...":"اكتب سؤالك هنا..."}" onkeydown="if(event.key==='Enter')sendChat()"><button class="btn" onclick="sendChat()">إرسال</button></div><div class="center-actions" style="margin-top:12px">${rp?"":`<button class="tab" onclick="quickAsk('اختبرني في المفردات')">اختبرني</button><button class="tab" onclick="quickAsk('اشرح لي قاعدة أساسية')">اشرح قاعدة</button>`}<button class="tab" onclick="clearChat()">🗑 ${rp?"إعادة الموقف":"محادثة جديدة"}</button></div></div>`;renderChat()}
function renderChat(){let c=$("#chat");if(!c)return;let l=LANGS.find(x=>x.id===lang),h=(chatHist[chatKey()]||[]).filter(m=>!m.hidden);c.innerHTML="";if(!h.length){addBubble(rp?"المشهد يبدأ الآن...":"مرحباً! أنا مساعدك التعليمي، وأفتكر محادثتنا حتى لو قفلت الصفحة. اسألني عن معنى كلمة، اطلب تدريباً، أو اكتب لي جملة بـ"+l.name+" وأنا أصححها لك.","ai")}else{h.forEach(m=>{let d=addBubble(m.content,m.role==="user"?"user":"ai");if(m.role!=="user")d.innerHTML=mdLite(m.content)})}c.scrollTop=c.scrollHeight}
function clearChat(){chatHist[chatKey()]=[];saveChats();if(rp){startRP(rp.id)}else{renderChat();toast("بدأنا محادثة جديدة في "+LANGS.find(x=>x.id===lang).name)}}
async function rpSend(text){let l=LANGS.find(x=>x.id===lang),h=chatHist[chatKey()];window.chatBusy=true;let wait=addBubble("...","ai");
try{let r=await fetch(AI_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:AI_MODEL,messages:[{role:"system",content:rpPrompt(l)}].concat(h.slice(-12).map(m=>({role:m.role,content:m.content})))})});if(r.status===429)throw new Error("limit");if(!r.ok)throw new Error("http");let j=await r.json(),t=j.choices&&j.choices[0]&&j.choices[0].message.content;if(!t)throw new Error("empty");h.push({role:"assistant",content:t});saveChats();wait.innerHTML=mdLite(t)}catch(e){h.pop();wait.textContent=e.message==="limit"?"وصلت للحد الأقصى من الرسائل حالياً. جرّب بعد قليل.":"تعذر الاتصال بالمدرس الآن. تأكد من الإنترنت وحاول مرة أخرى."}
window.chatBusy=false;let c=$("#chat");if(c)c.scrollTop=c.scrollHeight}
async function sendChat(){if(rp){let input=$("#chatInput"),s=input.value.trim();if(!s||window.chatBusy)return;addBubble(s,"user");input.value="";let h=chatHist[chatKey()];h.push({role:"user",content:s});saveChats();await rpSend(s);let n=h.filter(m=>m.role==="user"&&!m.hidden).length;if(n>=6&&(db.roleplayDone||[]).indexOf(chatKey())<0){db.roleplayDone.push(chatKey());db.points+=30;toast("أكملت محادثة الموقف! +30 نقطة 🎭")}db.points+=1;save();return}
let input=$("#chatInput"),s=input.value.trim();if(!s||window.chatBusy)return;addBubble(s,"user");input.value="";let l=LANGS.find(x=>x.id===lang),h=chatHist[lang]=chatHist[lang]||[];h.push({role:"user",content:s});saveChats();window.chatBusy=true;let wait=addBubble("...","ai");
try{let r=await fetch(AI_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:AI_MODEL,messages:[{role:"system",content:tutorPrompt(l)}].concat(h.slice(-12).map(m=>({role:m.role,content:m.content})))})});if(r.status===429)throw new Error("limit");if(!r.ok)throw new Error("http");let j=await r.json(),t=j.choices&&j.choices[0]&&j.choices[0].message.content;if(!t)throw new Error("empty");h.push({role:"assistant",content:t});saveChats();wait.innerHTML=mdLite(t);db.points+=1;save()}catch(e){h.pop();wait.textContent=e.message==="limit"?"وصلت للحد الأقصى من الرسائل حالياً. جرّب بعد قليل.":"تعذر الاتصال بالمدرس الآن. تأكد من الإنترنت وحاول مرة أخرى."}
window.chatBusy=false;let c=$("#chat");if(c)c.scrollTop=c.scrollHeight}

/* ===== Round 7: verb trainer, writing correction, word of the day ===== */
function wotd(){let day=new Date().toDateString();return LANGS.map(l=>{let pool=allWords.filter(w=>w.id===l.id),r=seedRnd(day+"|"+l.id),i=Math.floor(r()*pool.length);return{l,v:pool[i],i}})}
function wotdOpen(lid,i){flashFilter=lid;flash=i;go('vocabulary')}
let vrb=null;
function verbTable(v){let pro=VERB_PRONOUNS[lang];return `<div class="tbl-wrap"><table class="md-table"><tr><th>الضمير</th><th>التصريح</th></tr>${v[2].map((f,k)=>`<tr><td dir="auto">${pro[k]}</td><td dir="auto">${f} <button class="icon-btn sm" onclick="speak('${f.replace(/'/g,"\\'")}','${lang}')">🔊</button></td></tr>`).join("")}</table></div>`}
function verbHome(){let l=LANGS.find(x=>x.id===lang);$("#prac").innerHTML=`<div class="quiz-box"><div class="empty"><div style="font-size:36px">🔠</div><b>مدرب تصريف الأفعال · ${l.name}</b><p class="subtext" style="margin:10px 0">نعطيك الفعل والضمير وأنت تكتب التصريح الصحيح في زمن المضارع. التصحيح يتجاهل الحروف الكبيرة والترقيم ولهجات الحروف، ويمكنك فتح جدول التصريف أثناء التمرين.</p><p class="subtext">تصريحاتك الصحيحة حتى الآن: ${db.verbCorrect||0}</p><button class="btn" onclick="startVerbs()">ابدأ التمرين · 6 أسئلة</button></div></div>`}
function startVerbs(){vrb={pick:sh(VERBS[lang]).slice(0,6).map(v=>({v,p:Math.floor(Math.random()*6)})),i:0,score:0};showVerb()}
function showVerb(){if(vrb.i>=vrb.pick.length){$("#prac").innerHTML=`<div class="quiz-box"><div class="empty"><div style="font-size:40px">${vrb.score>=5?"🏆":"🔠"}</div><h2>انتهى التمرين!</h2><p>تصريحات صحيحة: ${vrb.score} من ${vrb.pick.length}</p><p class="subtext">+${vrb.score*10} نقطة</p><div class="center-actions"><button class="btn" onclick="startVerbs()">تمرين جديد</button><button class="btn ghost" onclick="practicePage()">التمارين</button></div></div></div>`;return}
let it=vrb.pick[vrb.i],pro=VERB_PRONOUNS[lang];
$("#prac").innerHTML=`<div class="quiz-box"><div class="card-foot"><span>السؤال ${vrb.i+1} من ${vrb.pick.length}</span><span>⭐ ${db.points} نقطة</span></div><div class="track"><span style="width:${vrb.i/vrb.pick.length*100}%"></span></div><div class="question" style="font-size:16px">صرّف الفعل مع الضمير:</div><div class="foreign" dir="ltr" style="text-align:center">${it.v[0]} <small style="color:var(--muted);font-family:Cairo;font-size:12px">(${it.v[1]})</small> ← ${pro[it.p]}</div><div class="chat-input" style="margin-top:14px"><input id="vrbIn" class="field" dir="auto" placeholder="اكتب التصريح هنا..." autocomplete="off" onkeydown="if(event.key==='Enter')checkVerb()"><button class="btn" onclick="checkVerb()">تحقق</button></div><div class="feedback" id="vrbFb"></div><div class="center-actions"><button class="tab" onclick="toggleVerbTable()">📋 جدول التصريف</button></div><div id="vrbTbl" style="display:none;margin-top:12px">${verbTable(it.v)}</div></div>`;
setTimeout(()=>{let e=$("#vrbIn");if(e)e.focus()},60)}
function toggleVerbTable(){let t=$("#vrbTbl");if(t)t.style.display=t.style.display==="none"?"block":"none"}
function checkVerb(){let it=vrb.pick[vrb.i],inp=$("#vrbIn"),fb=$("#vrbFb");if(inp.disabled)return;let ok=normLis(inp.value)===normLis(it.v[2][it.p]);inp.disabled=true;
if(ok){vrb.score++;db.verbCorrect=(db.verbCorrect||0)+1;db.points+=10;fb.innerHTML="تصريح صحيح! +10 نقاط ✅"}else{fb.innerHTML='الصحيح: <b dir="auto">'+it.v[2][it.p]+'</b>'}
save();fb.insertAdjacentHTML("beforeend",` <button class="btn" onclick="vrb.i++;showVerb()">${vrb.i+1>=vrb.pick.length?"النتيجة":"التالي ←"}</button>`)}
function writeLeft(){let t=new Date().toDateString();if(!db.writeDay||db.writeDay.date!==t)return 3;return Math.max(0,3-db.writeDay.count)}
function writeHome(){let l=LANGS.find(x=>x.id===lang),left=writeLeft();$("#prac").innerHTML=`<div class="quiz-box"><b>✍️ تصحيح الكتابة الحرة · ${l.name}</b><p class="subtext" style="margin:10px 0">اكتب أي جمل بـ${l.name} والمدرس الذكي يصححها لك: يعرض النص الصحيح ويشرح كل خطأ في سطر واحد بالعربية. +20 نقطة لكل تصحيح · متبقٍ اليوم: ${left} من 3</p><textarea id="writeIn" class="field write-area" dir="auto" rows="5" placeholder="اكتب هنا بـ${l.name}..."></textarea><div class="center-actions" style="margin-top:12px"><button class="btn" id="writeBtn" onclick="checkWriting()" ${left?"":"disabled"}>صحّح كتابتي</button></div><div id="writeFb" style="margin-top:14px"></div></div>`}
async function checkWriting(){let ta=$("#writeIn"),s=ta.value.trim(),fb=$("#writeFb");if(!s){toast("اكتب جملة أولاً");return}
if(!writeLeft()){fb.innerHTML='<div class="note">وصلت للحد اليومي (3 تصحيحات). عاود غداً بإذن الله.</div>';return}
let l=LANGS.find(x=>x.id===lang);if(window.chatBusy)return;window.chatBusy=true;$("#writeBtn").disabled=true;fb.innerHTML='<div class="bubble ai">...</div>';
let sys=`أنت مصحح كتابة لطالب عربي يتعلم ${l.name} (${l.native}) بمستوى ${db.level[lang]}. صحح النص الذي يرسله. اعرض أولاً **النص الصحيح** كاملاً، ثم تحت عنوان قصير «الأخطاء» اشرح كل خطأ في سطر واحد بالعربية: الخطأ ثم الصواب ثم السبب باختصار (قاعدة، إملاء، أو تركيب). إذا كان النص سليماً فاذكر ذلك وشجعه بجملة، وإذا كان بلغة غير ${l.name} فاطلب منه بلطف الكتابة بـ${l.name}. استخدم ماركداون بسيطاً ولا تستعمل الخطوط الفاصلة ---.`;
try{let r=await fetch(AI_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:AI_MODEL,messages:[{role:"system",content:sys},{role:"user",content:s}]})});if(r.status===429)throw new Error("limit");if(!r.ok)throw new Error("http");let j=await r.json(),t=j.choices&&j.choices[0]&&j.choices[0].message.content;if(!t)throw new Error("empty");
let day=new Date().toDateString();db.writeDay={date:day,count:(db.writeDay&&db.writeDay.date===day?db.writeDay.count:0)+1};db.writeCount=(db.writeCount||0)+1;db.points+=20;db.minutes+=2;save();
fb.innerHTML='<div class="bubble ai" style="max-width:100%">'+mdLite(t)+'</div><div class="feedback" style="margin-top:8px">+20 نقطة ✅ · متبقٍ اليوم: '+writeLeft()+'</div>';ta.disabled=true;
fb.insertAdjacentHTML("beforeend",'<div class="center-actions" style="margin-top:10px"><button class="btn ghost" onclick="writeHome()">تصحيح جديد</button></div>')}catch(e){fb.innerHTML='<div class="note">'+(e.message==="limit"?"وصلت للحد الأقصى من الطلبات حالياً. جرّب بعد قليل.":"تعذر الاتصال بالمدرس الآن. تأكد من الإنترنت وحاول مرة أخرى.")+"</div>";$("#writeBtn").disabled=false}
window.chatBusy=false}
